const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext({
    viewport: { width: 2400, height: 1080 },
    deviceScaleFactor: 1,
  });
  const page = await context.newPage();

  const htmlPath = path.resolve('/app/output/poster.html');
  await page.goto('file://' + htmlPath, { waitUntil: 'networkidle', timeout: 30000 });

  // Wait for all infographic instances to render
  await page.waitForTimeout(3000);

  // Check for any SVG elements (infographic renders as SVG)
  await page.waitForSelector('svg', { timeout: 10000 }).catch(() => {
    console.log('No SVG found, proceeding anyway');
  });

  // Give extra time for complex charts and fonts
  await page.waitForTimeout(2000);

  // Get the poster element and take a screenshot of it
  const poster = await page.$('#poster');
  if (poster) {
    await poster.screenshot({
      path: '/app/output/final_poster.png',
      type: 'png',
    });
    console.log('Poster screenshot saved to /app/output/final_poster.png');
  } else {
    // Fallback: full page screenshot
    await page.screenshot({
      path: '/app/output/final_poster.png',
      type: 'png',
      fullPage: true,
    });
    console.log('Full page screenshot saved to /app/output/final_poster.png');
  }

  await browser.close();
})();

