const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext({
    viewport: { width: 2400, height: 1080 },
    deviceScaleFactor: 1,
  });
  const page = await context.newPage();

  // Collect console errors
  const errors = [];
  page.on('console', msg => {
    if (msg.type() === 'error') errors.push(msg.text());
  });
  page.on('pageerror', err => errors.push(err.message));

  const htmlPath = path.resolve('/app/output/poster.html');
  await page.goto('file://' + htmlPath, { waitUntil: 'networkidle', timeout: 30000 });

  // Wait for infographics to render
  await page.waitForTimeout(5000);

  // Wait for at least 2 SVGs to be rendered
  await page.waitForFunction(() => document.querySelectorAll('svg').length >= 2, { timeout: 10000 }).catch(() => {});

  await page.waitForTimeout(2000);

  const poster = await page.$('#poster');
  if (poster) {
    await poster.screenshot({
      path: '/app/output/final_poster.png',
      type: 'png',
    });
    console.log('Saved poster screenshot to /app/output/final_poster.png');
  } else {
    await page.screenshot({
      path: '/app/output/final_poster.png',
      type: 'png',
      fullPage: true,
    });
    console.log('Fallback: full page screenshot saved');
  }

  if (errors.length > 0) {
    console.log('Console errors:', errors.slice(0, 5));
  }

  // Verify dimensions
  const dims = await page.evaluate(() => {
    const el = document.getElementById('poster');
    if (!el) return null;
    const r = el.getBoundingClientRect();
    return { width: r.width, height: r.height, svgs: document.querySelectorAll('svg').length };
  });
  console.log('Poster dimensions:', JSON.stringify(dims));

  await browser.close();
  console.log('Done.');
})();

