arguments.command:
node -e "
const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  await page.setViewportSize({ width: 2400, height: 1080 });
  await page.goto('file:///app/output/poster.html', { waitUntil: 'networkidle', timeout: 30000 });
  await page.waitForTimeout(5000);

  const quality = await page.evaluate(() => {
    // Check all text content in infographic containers
    const igWraps = document.querySelectorAll('.infographic-wrap');
    const results = [];
    igWraps.forEach((wrap, i) => {
      const walker = document.createTreeWalker(wrap, NodeFilter.SHOW_TEXT);
      const texts = [];
      let node;
      while (node = walker.nextNode()) {
        const t = node.textContent.trim();
        if (t) texts.push(t);
      }
      results.push({ index: i, id: wrap.id || 'no-id', textCount: texts.length, content: texts.slice(0, 12) });
    });

    // Check metric cards
    const cards = document.querySelectorAll('.metric-card');
    const cardTexts = Array.from(cards).map(c => {
      const v = c.querySelector('.metric-value');
      return v ? v.textContent.trim() : 'no value';
    });

    return { infographics: results, metricCards: cardTexts, totalSvgs: document.querySelectorAll('svg').length };
  });
  console.log(JSON.stringify(quality, null, 2));
  await browser.close();
})();
" 2>&1

